-- Generated by `npm run db -- schema` from apps/backend/src/migrations.
-- Reference only; do not edit. Change the schema with a new migration.

CREATE TABLE agent_reviews(
      id TEXT PRIMARY KEY,
      class_id TEXT NOT NULL REFERENCES classes(id),
      student_id TEXT NOT NULL REFERENCES users(id),
      conversation_id TEXT REFERENCES conversations(id) ON DELETE SET NULL,
      message_id TEXT REFERENCES conversation_messages(id) ON DELETE SET NULL,
      kind TEXT NOT NULL,
      content TEXT NOT NULL,
      sources TEXT NOT NULL,
      issues TEXT NOT NULL,
      status TEXT NOT NULL CHECK(status IN ('pending','published','rejected')),
      final_content TEXT,
      created_at TEXT NOT NULL,
      resolved_at TEXT,
      resolved_by TEXT REFERENCES users(id)
    );

CREATE TABLE class_invitations(
      id TEXT PRIMARY KEY,
      class_id TEXT NOT NULL REFERENCES classes(id),
      email TEXT NOT NULL,
      name TEXT NOT NULL,
      invited_by TEXT NOT NULL REFERENCES users(id),
      status TEXT NOT NULL CHECK(status IN ('pending','accepted','declined','revoked')),
      created_at TEXT NOT NULL,
      responded_at TEXT,
      UNIQUE(class_id,email)
    );

CREATE TABLE classes(
  id TEXT PRIMARY KEY,
  teacher_id TEXT REFERENCES users(id),
  name TEXT NOT NULL,
  syllabus TEXT NOT NULL,
  material_version INTEGER NOT NULL DEFAULT 1
, join_code TEXT);

CREATE TABLE companion_chats(
  id TEXT PRIMARY KEY,
  class_id TEXT NOT NULL REFERENCES classes(id),
  teacher_id TEXT NOT NULL REFERENCES users(id),
  title TEXT NOT NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE companion_messages(
  id TEXT PRIMARY KEY,
  class_id TEXT NOT NULL REFERENCES classes(id),
  teacher_id TEXT NOT NULL REFERENCES users(id),
  role TEXT NOT NULL CHECK(role IN ('user','assistant')),
  content TEXT NOT NULL,
  sources TEXT NOT NULL DEFAULT '[]',
  created_at TEXT NOT NULL
, chat_id TEXT);

CREATE TABLE conversation_messages(
      id TEXT PRIMARY KEY,
      conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
      role TEXT NOT NULL CHECK(role IN ('user','assistant')),
      content TEXT NOT NULL,
      sources TEXT,
      grounded INTEGER,
      requires_human_review INTEGER,
      created_at TEXT NOT NULL
    );

CREATE TABLE conversations(
      id TEXT PRIMARY KEY,
      class_id TEXT NOT NULL REFERENCES classes(id),
      student_id TEXT NOT NULL REFERENCES users(id),
      title TEXT NOT NULL,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );

CREATE TABLE course_file_text(
      file_id TEXT PRIMARY KEY REFERENCES course_files(id) ON DELETE CASCADE,
      text TEXT NOT NULL
    );

CREATE TABLE course_files(
      id TEXT PRIMARY KEY,
      class_id TEXT NOT NULL REFERENCES classes(id),
      uploaded_by TEXT NOT NULL REFERENCES users(id),
      filename TEXT NOT NULL,
      mime_type TEXT NOT NULL,
      size_bytes INTEGER NOT NULL CHECK(size_bytes > 0),
      sha256 TEXT NOT NULL,
      content BLOB NOT NULL,
      status TEXT NOT NULL DEFAULT 'stored' CHECK(status IN ('stored','indexed','failed')),
      created_at TEXT NOT NULL
    );

CREATE TABLE events(
  id TEXT PRIMARY KEY,
  class_id TEXT REFERENCES classes(id),
  agent TEXT,
  action TEXT,
  details TEXT,
  student_id TEXT,
  job_id TEXT,
  created_at TEXT
);

CREATE TABLE gap_resolutions(
      gap_id TEXT PRIMARY KEY REFERENCES gaps(id) ON DELETE CASCADE,
      submission_id TEXT NOT NULL REFERENCES submissions(id),
      created_at TEXT NOT NULL
    );

CREATE TABLE gaps(
  id TEXT PRIMARY KEY,
  class_id TEXT REFERENCES classes(id),
  student_id TEXT REFERENCES users(id),
  topic TEXT,
  tag TEXT,
  section TEXT,
  status TEXT,
  severity INTEGER,
  source TEXT,
  intervention_id TEXT,
  updated_at TEXT,
  UNIQUE(class_id,student_id,tag)
);

CREATE TABLE interventions(
  id TEXT PRIMARY KEY,
  class_id TEXT REFERENCES classes(id),
  topic TEXT,
  tag TEXT,
  content TEXT,
  probe TEXT,
  targets TEXT,
  status TEXT,
  engine TEXT,
  created_at TEXT,
  approved_at TEXT
);

CREATE TABLE jobs(
  id TEXT PRIMARY KEY,
  class_id TEXT REFERENCES classes(id),
  actor_id TEXT REFERENCES users(id),
  kind TEXT,
  payload TEXT,
  status TEXT,
  result TEXT,
  error TEXT,
  created_at TEXT,
  updated_at TEXT
);

CREATE TABLE memberships(
  class_id TEXT REFERENCES classes(id),
  student_id TEXT REFERENCES users(id),
  PRIMARY KEY(class_id,student_id)
);

CREATE TABLE presentations(
  id TEXT PRIMARY KEY,
  class_id TEXT NOT NULL REFERENCES classes(id),
  title TEXT NOT NULL,
  slides TEXT NOT NULL,
  status TEXT NOT NULL CHECK(status IN ('draft','published')),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  published_at TEXT
);

CREATE TABLE probes(
  id TEXT PRIMARY KEY,
  gap_id TEXT REFERENCES gaps(id),
  student_id TEXT REFERENCES users(id),
  answer TEXT,
  correct INTEGER,
  created_at TEXT
);

CREATE TABLE questions(
  id TEXT PRIMARY KEY,
  class_id TEXT REFERENCES classes(id),
  student_id TEXT REFERENCES users(id),
  text TEXT,
  created_at TEXT
);

CREATE TABLE quizzes(
  id TEXT PRIMARY KEY,
  class_id TEXT REFERENCES classes(id),
  title TEXT,
  questions TEXT,
  status TEXT,
  engine TEXT,
  created_at TEXT
);

CREATE TABLE schema_migrations(id TEXT PRIMARY KEY,applied_at TEXT NOT NULL);

CREATE TABLE sessions(
  token_hash TEXT PRIMARY KEY,
  user_id TEXT REFERENCES users(id),
  expires_at INTEGER NOT NULL
);

CREATE TABLE sources(
  id TEXT PRIMARY KEY,
  class_id TEXT NOT NULL REFERENCES classes(id),
  type TEXT NOT NULL CHECK(type IN ('deck','link')),
  name TEXT NOT NULL,
  url TEXT,
  status TEXT NOT NULL CHECK(status IN ('processing','ready','failed')),
  error TEXT,
  content TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL
);

CREATE TABLE submissions(
  id TEXT PRIMARY KEY,
  quiz_id TEXT REFERENCES quizzes(id),
  student_id TEXT REFERENCES users(id),
  answers TEXT,
  results TEXT,
  score REAL,
  total REAL,
  confidence REAL,
  status TEXT,
  reason TEXT,
  created_at TEXT,
  UNIQUE(quiz_id,student_id)
);

CREATE TABLE users(
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  email TEXT UNIQUE NOT NULL,
  role TEXT CHECK(role IN ('teacher','student')),
  password TEXT NOT NULL
);

CREATE TABLE wellbeing_flags(
  id TEXT PRIMARY KEY,
  class_id TEXT NOT NULL REFERENCES classes(id),
  student_id TEXT NOT NULL REFERENCES users(id),
  source TEXT NOT NULL CHECK(source IN ('question','assistant')),
  text TEXT NOT NULL,
  category TEXT NOT NULL,
  severity TEXT NOT NULL CHECK(severity IN ('urgent','high','medium','low')),
  status TEXT NOT NULL DEFAULT 'new' CHECK(status IN ('new','reached_out','resolved')),
  note TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE workflow_runs(
      id TEXT PRIMARY KEY,
      class_id TEXT NOT NULL REFERENCES classes(id),
      kind TEXT NOT NULL CHECK(kind IN ('study','quiz_draft','quiz_submission','explanation','follow_up')),
      title TEXT NOT NULL,
      status TEXT NOT NULL CHECK(status IN ('running','awaiting_review','complete','failed','rejected')),
      student_id TEXT REFERENCES users(id),
      job_id TEXT UNIQUE REFERENCES jobs(id) ON DELETE SET NULL,
      entity_id TEXT,
      conversation_id TEXT REFERENCES conversations(id) ON DELETE CASCADE,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );

CREATE TABLE workflow_steps(
      id TEXT PRIMARY KEY,
      run_id TEXT NOT NULL REFERENCES workflow_runs(id) ON DELETE CASCADE,
      position INTEGER NOT NULL CHECK(position > 0),
      actor TEXT NOT NULL,
      action TEXT NOT NULL,
      detail TEXT NOT NULL,
      state TEXT NOT NULL CHECK(state IN ('complete','pending','failed')),
      sources TEXT NOT NULL DEFAULT '[]',
      created_at TEXT NOT NULL,
      UNIQUE(run_id,position)
    );

CREATE INDEX agent_reviews_class ON agent_reviews(class_id,status,created_at);

CREATE INDEX class_invitations_email ON class_invitations(email,status);

CREATE UNIQUE INDEX classes_join_code ON classes(join_code);

CREATE INDEX companion_chats_owner ON companion_chats(class_id,teacher_id,updated_at);

CREATE INDEX companion_messages_chat ON companion_messages(chat_id);

CREATE INDEX companion_messages_thread ON companion_messages(class_id,teacher_id);

CREATE INDEX conversation_messages_order ON conversation_messages(conversation_id,created_at);

CREATE INDEX conversations_student ON conversations(student_id,class_id,updated_at);

CREATE INDEX course_files_class ON course_files(class_id,created_at);

CREATE INDEX event_class ON events(class_id,created_at);

CREATE INDEX gap_class ON gaps(class_id,status);

CREATE INDEX presentations_class ON presentations(class_id);

CREATE INDEX sources_class ON sources(class_id);

CREATE UNIQUE INDEX sources_class_url ON sources(class_id,url) WHERE url IS NOT NULL;

CREATE INDEX submission_student ON submissions(student_id);

CREATE INDEX wellbeing_flags_class ON wellbeing_flags(class_id,status);

CREATE INDEX workflow_runs_class ON workflow_runs(class_id,created_at DESC);

CREATE INDEX workflow_runs_entity ON workflow_runs(kind,entity_id);
